FUNCTION_BLOCK FB_Subsea_MultiphaseHelicoAxialPump
(*
========================================================================================================================
  PROJECT      : ULTRA-DEEPWATER SUBSEA MULTIPHASE BOOSTING STATION (WATER DEPTH: 2,850 METERS)
  SUBSYSTEM    : HELICO-AXIAL MULTIPHASE COMPRESSOR / PUMP HYDRAULICS & ANTI-RECIRCULATION VALVE (ARV)
  EQUIPMENT TAG: 20-KA-101 / 20-FV-104 ANTI-SURGE & RECIRCULATION DIVERTER LOOP
  DESIGNATION  : SIL-3 SAFETY INSTRUMENTED SYSTEM (SIS) / CYBER-PHYSICAL PRODUCTION CONTROL (CPPS)
  SPECIFICATION: IEC 61131-3 3RD ED. / ISO 13628-6 SUBSEA PRODUCTION CONTROL SYSTEMS / API 17S / ISA-18.2
  AUTHOR       : PRINCIPAL AUTOMATION FELLOW & CYBER-PHYSICAL SYSTEMS CHAIR (LUMINA SWARM)
------------------------------------------------------------------------------------------------------------------------
  THEORETICAL FORMULATION & MULTIPHASE HYDRODYNAMICS:

    1. HELICO-AXIAL PUMP COMPRESSION KINETICS & GAS VOLUME FRACTION (GVF) TRANSIENTS:
       Helico-axial compression combines the high volumetric handling capacity of axial compressors with the
       viscous and dense fluid capability of centrifugal pumps across 12-16 proprietary rotor/stator stages.
       The local Gas Volume Fraction (GVF, alpha) is defined at in-situ conditions:
           GVF = alpha = Q_gas / (Q_gas + Q_liquid) * 100.0  [%]
       The homogeneous multiphase mixture density rho_mix is governed by:
           rho_mix = (alpha / 100.0) * rho_gas + (1.0 - (alpha / 100.0)) * rho_liquid  [kg/m3]
       Under pure liquid slugs (alpha -> 0%), density increases by up to 50x, producing severe hydraulic torque loads:
           Torque_hyd = (rho_mix * Q_total * Delta_H_Euler) / (omega * eta_hyd)
       Under severe gas slugs or gas pockets (alpha -> 95-100%):
           Compressor encounters hydrodynamic stall and rapid adiabatic temperature runaway due to reduced heat
           capacity of the carrier gas. Unmitigated gas locks collapse the dynamic head, risking compressor surge.

    2. DYNAMIC ANTI-RECIRCULATION VALVE (ARV) & MULTIPHASE SURGE MARGIN:
       Unlike single-phase gas compressors, helico-axial surge and minimum-flow limits shift dynamically with GVF:
           Q_surge(N, GVF) = (k0 + k1 * (N / N_rated) + k2 * (N / N_rated)^2) * (1.0 + k_gvf * (GVF / 100.0)^2)
       The instantaneous surge margin S_m is defined by:
           S_m = (Q_multiphase_actual - Q_surge(N, GVF)) / Q_surge(N, GVF)
       The Anti-Recirculation Valve (ARV) serves a dual functional safety role:
         a) Recirculates dense liquid/gas from discharge to inlet, preventing low-flow hydrodynamic stall and surge.
         b) Acts as an instantaneous gas-lock attenuator by re-injecting cooler high-pressure multiphase liquid into
            the suction mixer when inlet GVF spikes >85%, preventing rotor thermal expansion and bearing damage.

    3. SUBSEA INTEGRITY CONSTRAINTS (DEEPWATER ENVIRONMENT: 285 bar ambient, 2.5 deg C):
         a) Natural Gas Hydrate Formation Dissociation Margin:
            T_hydrate_dissoc = 8.9 * LN(P_suction_bar) - 28.5  [deg C]
            Operating subcooling margin: Margin_hyd = T_process_inlet - T_hydrate_dissoc.
            If Margin_hyd < 5.0 deg C, hydrate inhibitor dosing (MEG) or thermal recycle must be initiated.
         b) Subsea Barrier Fluid Overpressure System:
            Delta_P_barrier = P_barrier - MAX(P_suction, P_discharge) >= 20.0 bar.
            Loss of barrier overpressure threatens canned motor stator hermetic isolation and bearing lubricity.

    4. MULTI-VARIABLE STATE-SPACE MPC FORMULATION (dt = 0.5 s):
       Discrete Plant Dynamics:
           x[k+1] = A * x[k] + B * u[k] + E * d[k]
           y[k]   = C * x[k] + D * u[k]
       State Vector:
           x = [ Delta_P_boost [bar], GVF_error [%], Rotor_Speed_Dev [rpm], Delta_T_discharge [deg C] ]^T
       Control Inputs:
           u = [ ARV_Position_Cmd [%], VSD_Speed_Setpoint_Cmd [rpm] ]^T
       Disturbances:
           d = [ d(Inlet_Pressure)/dt [bar/s], d(GVF)/dt [%/s] ]^T (Derived from upstream subsea slug trackers)

    5. TRIPLE MODULAR REDUNDANCY (2oo3 TMR) SENSOR VOTING ARCHITECTURE:
       Three subsea resonant quartz pressure transmitters continuously sense suction manifold pressure.
       Voting logic implements automated outlier rejection, cross-channel deviation drift detection,
       and bumpless degradation through 2oo3 -> 2oo2 -> 1oo1 -> failsafe hold modes.
========================================================================================================================
*)

VAR_INPUT
    (* --- Master Permissives & Safety Loop --- *)
    bMasterEnable               : BOOL;     (* Master process train execution permissive [TRUE=Run Permitted] *)
    bSubseaSafetyEStopOk        : BOOL;     (* Hardwired SIL-3 subsea safety loop / ESD trip [TRUE=Healthy, FALSE=Tripped] *)
    bAutoModeSelect             : BOOL;     (* Closed-loop Model Predictive Control vs Coordinated Manual [TRUE=Auto] *)
    bMegInjectionActive         : BOOL;     (* Subsea Monoethylene Glycol hydrate inhibitor injection active feedback *)

    (* --- Triple Redundant Primary Pressure Sensors (2oo3 Voting) --- *)
    rInletPressure_A_bar        : REAL;     (* Subsea suction manifold resonant quartz sensor Ch-A [bar] (0.0 .. 400.0) *)
    rInletPressure_B_bar        : REAL;     (* Subsea suction manifold resonant quartz sensor Ch-B [bar] (0.0 .. 400.0) *)
    rInletPressure_C_bar        : REAL;     (* Subsea suction manifold resonant quartz sensor Ch-C [bar] (0.0 .. 400.0) *)

    (* --- Subsea Manifold Process Instruments --- *)
    rDischargePressure_bar      : REAL;     (* Compressor discharge manifold header pressure [bar] (0.0 .. 500.0) *)
    rMultiphaseInflow_m3h       : REAL;     (* Total in-situ multiphase mixture flow rate from subsea MPFM [m3/h] (0..2500) *)
    rGasVolumeFraction_Pct      : REAL;     (* In-situ Gas Volume Fraction from dual-energy gamma densitometer [%] (0..100) *)
    rProcessTempInlet_DegC      : REAL;     (* Subsea suction process temperature [deg C] (-10.0 .. 80.0) *)
    rProcessTempOutlet_DegC     : REAL;     (* Subsea discharge process temperature [deg C] (-10.0 .. 150.0) *)

    (* --- VSD Drive & Subsea Motor Health Telemetry --- *)
    rPumpSpeedFeedback_rpm      : REAL;     (* Subsea permanent magnet motor actual shaft speed [rpm] (0 .. 6500) *)
    rMotorCurrent_A             : REAL;     (* Subsea motor stator phase current feedback [A] (0 .. 600) *)
    rMotorShaftTorque_kNm       : REAL;     (* Shaft electromagnetic torque from VSD active flux vector [kNm] (0..25) *)
    rMotorWindingTemp_DegC      : REAL;     (* Subsea stator winding RTD temperature [deg C] (0.0 .. 180.0) *)
    rBarrierFluidDiffPress_bar  : REAL;     (* Motor barrier fluid overpressure relative to process [bar] (0.0 .. 80.0) *)

    (* --- Recirculation Valve Telemetry --- *)
    rRecircValveFeedback_Pct    : REAL;     (* Subsea hydraulic step-choke ARV position feedback [%] (0.0=Closed..100.0=Open) *)
END_VAR

VAR_OUTPUT
    (* --- Actuation Commands to Subsea Hardware --- *)
    bSystemReady                : BOOL;     (* Subsea boosting module fully operational and within operating envelope *)
    bDegradedModeActive         : BOOL;     (* Module operating in degraded sensor or reduced-margin fallback mode *)
    rRecirculationValve_Pct     : REAL;     (* Anti-Recirculation Valve (ARV) position command setpoint [%] (0.0 .. 100.0) *)
    rVsdSpeedSetpoint_rpm       : REAL;     (* Variable Speed Drive rotor speed command setpoint [rpm] (0 .. 6000) *)

    (* --- Validated Process Parameters & Performance Metrics --- *)
    rVotedInletPress_bar        : REAL;     (* 2oo3 TMR resolved validated subsea suction pressure [bar] *)
    rDifferentialPress_bar      : REAL;     (* Net differential pressure boost generated across compressor stages [bar] *)
    rSurgeMargin_Pct            : REAL;     (* Real-time calculated multiphase surge margin percentage [%] (Target >= 15%) *)
    rHydrateMargin_DegC         : REAL;     (* Thermal safety margin above natural gas hydrate dissociation curve [deg C] *)
    rCalculatedMixDensity_kgm3  : REAL;     (* In-situ multiphase mixture density at compressor suction [kg/m3] *)

    (* --- Diagnostic Registers & Status Words --- *)
    wAlarmWord                  : WORD;     (* ISA-18.2 packed alarm status word *)
    wSystemStatusWord           : WORD;     (* Comprehensive system state machine and subsea health status word *)
END_VAR

VAR
    (* --- Finite State Machine Supervisory Registers --- *)
    iState                      : INT := 0; (* Active operational state index *)
    iPreviousState              : INT := 0; (* Historical state transition tracker *)
    udiStateRunTimeCycles       : UDINT := 0; (* Execution cycles accumulated in current state *)

    (* --- Triple Modular Redundancy (2oo3 TMR) Voting Registers --- *)
    bSensorA_Valid              : BOOL := TRUE;
    bSensorB_Valid              : BOOL := TRUE;
    bSensorC_Valid              : BOOL := TRUE;
    iHealthySensorCount         : INT  := 3;
    rDeltaAB                    : REAL := 0.0;
    rDeltaBC                    : REAL := 0.0;
    rDeltaCA                    : REAL := 0.0;
    rTmrToleranceLimit_bar      : REAL := 2.50; (* Maximum allowable discrepancy before sensor channel drift trip [bar] *)

    (* --- Multiphase Compressor Hydrodynamic Characterization Constants --- *)
    rRatedSpeed_rpm             : REAL := 5400.0; (* Rated mechanical shaft speed [rpm] *)
    rMinSpeed_rpm               : REAL := 1800.0; (* Minimum continuous hydrodynamic hydrodynamic speed [rpm] *)
    rMaxSpeed_rpm               : REAL := 6000.0; (* Overspeed trip prevention operational ceiling [rpm] *)
    rMaxDischargePress_bar      : REAL := 380.0;  (* Subsea manifold mechanical design pressure limit [bar] *)
    rTargetDiffPress_bar        : REAL := 65.0;   (* Target production differential pressure boost [bar] *)
    rMaxMotorTorque_kNm         : REAL := 18.5;   (* Maximum continuous shaft torque rating [kNm] *)
    rMaxMotorCurrent_A          : REAL := 480.0;  (* Maximum continuous motor winding current limit [A] *)

    (* Surge Line Polynomial Coefficients: Q_surge = (k0 + k1*n + k2*n^2) * (1 + k_gvf*alpha^2) *)
    rK0_Surge                   : REAL := 120.0;
    rK1_Surge                   : REAL := 340.0;
    rK2_Surge                   : REAL := 190.0;
    rK_Gvf_Surge                : REAL := 1.85;

    (* Fluid Properties Approximations *)
    rRhoGasBase_kgm3            : REAL := 95.0;   (* In-situ gas density at suction pressure 180 bar [kg/m3] *)
    rRhoLiquidBase_kgm3         : REAL := 820.0;  (* Degassed subsea crude oil and formation water mixture [kg/m3] *)

    (* --- State-Space Discrete Model Representation (Sample Time dt = 0.5 s) --- *)
    (* State Vector x:
         x[0] = Delta_P_boost error (rDifferentialPress_bar - rTargetDiffPress_bar) [bar]
         x[1] = GVF trend / deviation [ % ]
         x[2] = Speed deviation (rPumpSpeedFeedback_rpm - Speed_Setpoint) [rpm]
         x[3] = Stage thermal delta (rProcessTempOutlet_DegC - rProcessTempInlet_DegC) [deg C]
    *)
    rState_x1_DiffPressErr      : REAL := 0.0;
    rState_x2_GvfDeviation      : REAL := 0.0;
    rState_x3_SpeedError        : REAL := 0.0;
    rState_x4_ThermalDelta      : REAL := 0.0;

    (* Linearized Plant Transition Matrix A (4x4) *)
    rA11 : REAL := 0.9150;  rA12 : REAL := -0.2800; rA13 : REAL := 0.0125;  rA14 : REAL := -0.0050;
    rA21 : REAL := 0.0000;  rA22 : REAL := 0.8200;  rA23 : REAL := 0.0000;  rA24 : REAL := 0.0000;
    rA31 : REAL := -0.0450; rA32 : REAL := 0.1200;  rA33 : REAL := 0.9400;  rA34 : REAL := 0.0000;
    rA41 : REAL := 0.0180;  rA42 : REAL := 0.1550;  rA43 : REAL := 0.0020;  rA44 : REAL := 0.8850;

    (* Linearized Plant Control Input Matrix B (4x2): u = [Delta_ARV [%], Delta_VSD_Setpoint [rpm]] *)
    rB11 : REAL := -0.4200; rB12 : REAL := 0.0240; (* ARV opening drops dP; VSD speed increases dP *)
    rB21 : REAL := -0.1800; rB22 : REAL := 0.0000; (* ARV re-injects liquid, decreasing suction GVF *)
    rB31 : REAL := 0.0800;  rB32 : REAL := 0.8500;  (* ARV relieves torque; VSD setpoint drives speed *)
    rB41 : REAL := -0.2200; rB42 : REAL := 0.0110; (* ARV liquid recirculation cools compressor stages *)

    (* Disturbance Matrix E (4x2): d = [d(Inlet_Pressure)/dt, d(GVF)/dt] *)
    rE11 : REAL := -0.8500; rE12 : REAL := -0.3500;
    rE21 : REAL := 0.0500;  rE22 : REAL := 0.9200;
    rE31 : REAL := -0.1500; rE32 : REAL := 0.4200;
    rE41 : REAL := 0.0000;  rE42 : REAL := 0.2800;

    (* Model Predictive Horizon Predictions *)
    rPredDiffPress_bar          : REAL := 0.0;
    rPredGvf_Pct                : REAL := 0.0;
    rPredThermalDelta_DegC      : REAL := 0.0;

    (* Signal Conditioning, Derivatives & Digital Low-Pass Filters *)
    rInletPress_Filt_bar        : REAL := 150.0;
    rDischargePress_Filt_bar    : REAL := 215.0;
    rFlow_Filt_m3h              : REAL := 800.0;
    rGvf_Filt_Pct               : REAL := 65.0;
    rPrevInletPress_bar         : REAL := 150.0;
    rPrevGvf_Pct                : REAL := 65.0;
    rInletPressRate_bars        : REAL := 0.0;
    rGvfRate_Pcts               : REAL := 0.0;

    (* Calculated Hydrodynamic Limits *)
    rDynamicSurgeFlow_m3h       : REAL := 250.0;
    rNormSpeed                  : REAL := 0.0;

    (* Natural Gas Hydrate Equilibrium Tracking *)
    rHydrateDissocTemp_DegC     : REAL := 15.0;

    (* Timers & Watchdogs *)
    tonStartupPermissive        : TON;
    tonSlugDebounce             : TON;
    tonGasLockPersistence       : TON;
    tonBarrierFluidTripDebounce : TON;
    tonHydrateSubcoolWarning    : TON;

    (* Statistical & Maintenance Accumulators *)
    udiTotalExecutionCycles     : UDINT := 0;
    udiGasSlugEventCounter      : UDINT := 0;
    udiLiquidSlugEventCounter   : UDINT := 0;
    rCumulativeRecircTime_Hours : REAL  := 0.0;
END_VAR

(*
========================================================================================================================
  CYCLIC EXECUTION CODE
========================================================================================================================
*)

udiTotalExecutionCycles := udiTotalExecutionCycles + 1;
udiStateRunTimeCycles   := udiStateRunTimeCycles + 1;

(* ---------------------------------------------------------------------------------------------------------------------
   LAYER 1: SIL-3 HARDWIRED SAFETY INTERLOCKS, BARRIER FLUID PRESERVATION & FIRST-OUT TRIPS
   --------------------------------------------------------------------------------------------------------------------- *)
(* Barrier fluid differential pressure watchdog debounce: 2.0 second trip window *)
tonBarrierFluidTripDebounce(
    IN := (rBarrierFluidDiffPress_bar < 20.0) AND (iState > 0),
    PT := T#2S
);

IF (NOT bSubseaSafetyEStopOk) OR tonBarrierFluidTripDebounce.Q OR (rDischargePressure_bar > rMaxDischargePress_bar) THEN
    (* Immediate Failsafe De-energization *)
    bSystemReady            := FALSE;
    bDegradedModeActive     := FALSE;
    rVsdSpeedSetpoint_rpm   := 0.0;   (* Coast subsea motor to zero speed *)
    rRecirculationValve_Pct := 100.0; (* 100% Full Open ARV: Rapid subsea pressure equalization & hydrate prevention *)

    (* Alarm Word Mapping *)
    wAlarmWord.0 := NOT bSubseaSafetyEStopOk;            (* Bit 0: Emergency Stop Loop Tripped *)
    wAlarmWord.1 := tonBarrierFluidTripDebounce.Q;        (* Bit 1: Barrier Fluid Critical Depressurization Trip *)
    wAlarmWord.9 := (rDischargePressure_bar > rMaxDischargePress_bar); (* Bit 9: Discharge Overpressure Trip *)

    wSystemStatusWord := 16#F000; (* Trip Status *)
    iState            := 99;      (* Lock into Emergency State *)
    RETURN;
END_IF;

wAlarmWord.0 := FALSE;
wAlarmWord.1 := FALSE;
wAlarmWord.9 := FALSE;

(* ---------------------------------------------------------------------------------------------------------------------
   LAYER 2: TRIPLE MODULAR REDUNDANCY (2oo3 TMR) SENSOR VOTING ALGORITHM FOR SUCTION PRESSURE
   --------------------------------------------------------------------------------------------------------------------- *)
(* Step 2.1: Plausibility boundary validation [10.0 bar to 380.0 bar] *)
bSensorA_Valid := (rInletPressure_A_bar >= 10.0) AND (rInletPressure_A_bar <= 380.0);
bSensorB_Valid := (rInletPressure_B_bar >= 10.0) AND (rInletPressure_B_bar <= 380.0);
bSensorC_Valid := (rInletPressure_C_bar >= 10.0) AND (rInletPressure_C_bar <= 380.0);

(* Step 2.2: Inter-sensor discrepancy delta evaluation *)
rDeltaAB := ABS(rInletPressure_A_bar - rInletPressure_B_bar);
rDeltaBC := ABS(rInletPressure_B_bar - rInletPressure_C_bar);
rDeltaCA := ABS(rInletPressure_C_bar - rInletPressure_A_bar);

(* Step 2.3: Voting logic with selective outlier rejection *)
IF bSensorA_Valid AND bSensorB_Valid AND bSensorC_Valid THEN
    IF (rDeltaAB <= rTmrToleranceLimit_bar) AND (rDeltaBC <= rTmrToleranceLimit_bar) AND (rDeltaCA <= rTmrToleranceLimit_bar) THEN
        (* All three sensors coherent: Full 2oo3 mean *)
        rVotedInletPress_bar := (rInletPressure_A_bar + rInletPressure_B_bar + rInletPressure_C_bar) / 3.0;
        iHealthySensorCount  := 3;
        wAlarmWord.2         := FALSE; (* TMR Divergence Warning cleared *)
        wAlarmWord.3         := FALSE;
    ELSIF (rDeltaAB <= rTmrToleranceLimit_bar) AND (rDeltaBC > rTmrToleranceLimit_bar) THEN
        (* Sensor C has drifted out of tolerance: Reject C, average A and B *)
        rVotedInletPress_bar := (rInletPressure_A_bar + rInletPressure_B_bar) / 2.0;
        bSensorC_Valid       := FALSE;
        iHealthySensorCount  := 2;
        wAlarmWord.2         := TRUE;  (* Sensor C drift detected *)
    ELSIF (rDeltaBC <= rTmrToleranceLimit_bar) AND (rDeltaAB > rTmrToleranceLimit_bar) THEN
        (* Sensor A has drifted out of tolerance: Reject A, average B and C *)
        rVotedInletPress_bar := (rInletPressure_B_bar + rInletPressure_C_bar) / 2.0;
        bSensorA_Valid       := FALSE;
        iHealthySensorCount  := 2;
        wAlarmWord.2         := TRUE;  (* Sensor A drift detected *)
    ELSIF (rDeltaCA <= rTmrToleranceLimit_bar) AND (rDeltaAB > rTmrToleranceLimit_bar) THEN
        (* Sensor B has drifted out of tolerance: Reject B, average A and C *)
        rVotedInletPress_bar := (rInletPressure_A_bar + rInletPressure_C_bar) / 2.0;
        bSensorB_Valid       := FALSE;
        iHealthySensorCount  := 2;
        wAlarmWord.2         := TRUE;  (* Sensor B drift detected *)
    ELSE
        (* Total TMR Incoherence: Dual drift event, compute median *)
        IF (rInletPressure_A_bar >= rInletPressure_B_bar AND rInletPressure_A_bar <= rInletPressure_C_bar) OR
           (rInletPressure_A_bar <= rInletPressure_B_bar AND rInletPressure_A_bar >= rInletPressure_C_bar) THEN
            rVotedInletPress_bar := rInletPressure_A_bar;
        ELSIF (rInletPressure_B_bar >= rInletPressure_A_bar AND rInletPressure_B_bar <= rInletPressure_C_bar) OR
              (rInletPressure_B_bar <= rInletPressure_A_bar AND rInletPressure_B_bar >= rInletPressure_C_bar) THEN
            rVotedInletPress_bar := rInletPressure_B_bar;
        ELSE
            rVotedInletPress_bar := rInletPressure_C_bar;
        END_IF;
        iHealthySensorCount := 1;
        wAlarmWord.2        := TRUE;
        wAlarmWord.3        := TRUE; (* TMR Disagreement Fault *)
    END_IF;
ELSIF bSensorA_Valid AND bSensorB_Valid THEN
    rVotedInletPress_bar := (rInletPressure_A_bar + rInletPressure_B_bar) / 2.0;
    iHealthySensorCount  := 2;
    wAlarmWord.2         := TRUE;
ELSIF bSensorB_Valid AND bSensorC_Valid THEN
    rVotedInletPress_bar := (rInletPressure_B_bar + rInletPressure_C_bar) / 2.0;
    iHealthySensorCount  := 2;
    wAlarmWord.2         := TRUE;
ELSIF bSensorC_Valid AND bSensorA_Valid THEN
    rVotedInletPress_bar := (rInletPressure_A_bar + rInletPressure_C_bar) / 2.0;
    iHealthySensorCount  := 2;
    wAlarmWord.2         := TRUE;
ELSIF bSensorA_Valid THEN
    rVotedInletPress_bar := rInletPressure_A_bar;
    iHealthySensorCount  := 1;
    wAlarmWord.3         := TRUE;
ELSIF bSensorB_Valid THEN
    rVotedInletPress_bar := rInletPressure_B_bar;
    iHealthySensorCount  := 1;
    wAlarmWord.3         := TRUE;
ELSIF bSensorC_Valid THEN
    rVotedInletPress_bar := rInletPressure_C_bar;
    iHealthySensorCount  := 1;
    wAlarmWord.3         := TRUE;
ELSE
    (* Total Sensor Failure: Conservative safe estimate from discharge minus minimal head *)
    rVotedInletPress_bar := rDischargePressure_bar - 15.0;
    iHealthySensorCount  := 0;
    wAlarmWord.3         := TRUE; (* Sensor Loss Alarm *)
END_IF;

(* ---------------------------------------------------------------------------------------------------------------------
   LAYER 3: THERMODYNAMIC, HYDRODYNAMIC & HYDRATE CHARACTERIZATION CALCULATIONS
   --------------------------------------------------------------------------------------------------------------------- *)
(* 1st-Order Low-Pass Filter on Critical Feedback Signals (Sample dt = 0.5 s, tau = 1.5 s) *)
rInletPress_Filt_bar     := (rInletPress_Filt_bar * 0.75) + (rVotedInletPress_bar * 0.25);
rDischargePress_Filt_bar := (rDischargePress_Filt_bar * 0.75) + (rDischargePressure_bar * 0.25);
rFlow_Filt_m3h          := (rFlow_Filt_m3h * 0.70) + (rMultiphaseInflow_m3h * 0.30);
rGvf_Filt_Pct           := (rGvf_Filt_Pct * 0.80) + (rGasVolumeFraction_Pct * 0.20);

(* Measured Differential Pressure Across Helico-Axial Compressor Stages *)
rDifferentialPress_bar := rDischargePress_Filt_bar - rInletPress_Filt_bar;
IF rDifferentialPress_bar < 0.0 THEN
    rDifferentialPress_bar := 0.0;
END_IF;

(* In-situ Multiphase Mixture Density Calculation [kg/m3] *)
rCalculatedMixDensity_kgm3 := ((rGvf_Filt_Pct / 100.0) * rRhoGasBase_kgm3) + 
                              ((1.0 - (rGvf_Filt_Pct / 100.0)) * rRhoLiquidBase_kgm3);

(* Upstream Disturbance Rate of Change (Derivatives across 0.5 s timestep) *)
rInletPressRate_bars := (rVotedInletPress_bar - rPrevInletPress_bar) / 0.5;
rGvfRate_Pcts        := (rGasVolumeFraction_Pct - rPrevGvf_Pct) / 0.5;
rPrevInletPress_bar  := rVotedInletPress_bar;
rPrevGvf_Pct         := rGasVolumeFraction_Pct;

(* Dynamic Multiphase Surge Flow Limit Calculation *)
rNormSpeed := rPumpSpeedFeedback_rpm / rRatedSpeed_rpm;
IF rNormSpeed < 0.20 THEN
    rNormSpeed := 0.20;
END_IF;

rDynamicSurgeFlow_m3h := (rK0_Surge + (rK1_Surge * rNormSpeed) + (rK2_Surge * rNormSpeed * rNormSpeed)) * 
                         (1.0 + (rK_Gvf_Surge * (rGvf_Filt_Pct / 100.0) * (rGvf_Filt_Pct / 100.0)));

(* Multiphase Surge Margin Calculation [%] *)
IF rDynamicSurgeFlow_m3h > 1.0 THEN
    rSurgeMargin_Pct := ((rFlow_Filt_m3h - rDynamicSurgeFlow_m3h) / rDynamicSurgeFlow_m3h) * 100.0;
ELSE
    rSurgeMargin_Pct := 100.0;
END_IF;

(* Natural Gas Hydrate Dissociation Temperature Prediction & Subcooling Margin *)
IF rVotedInletPress_bar > 1.0 THEN
    rHydrateDissocTemp_DegC := (8.9 * LN(rVotedInletPress_bar)) - 28.5;
ELSE
    rHydrateDissocTemp_DegC := 0.0;
END_IF;
rHydrateMargin_DegC := rProcessTempInlet_DegC - rHydrateDissocTemp_DegC;

(* Hydrate Risk Alarm Debounce (Margin < 4.0 deg C) *)
tonHydrateSubcoolWarning(IN := (rHydrateMargin_DegC < 4.0) AND NOT bMegInjectionActive, PT := T#5S);
wAlarmWord.8 := tonHydrateSubcoolWarning.Q; (* Bit 8: Hydrate Formation Risk *)

(* Multiphase Surge Critical Alarm (Margin < 12%) *)
wAlarmWord.5 := (rSurgeMargin_Pct < 12.0); (* Bit 5: Surge Margin Critical *)

(* ---------------------------------------------------------------------------------------------------------------------
   LAYER 4: STATE-SPACE PREDICTIVE MODEL & MULTI-OBJECTIVE MPC ALGORITHM
   --------------------------------------------------------------------------------------------------------------------- *)
(* Update State Vector Deviations *)
rState_x1_DiffPressErr := rDifferentialPress_bar - rTargetDiffPress_bar;
rState_x2_GvfDeviation := rGvf_Filt_Pct - 70.0; (* Baseline nominal GVF operating design point *)
rState_x3_SpeedError   := rPumpSpeedFeedback_rpm - rVsdSpeedSetpoint_rpm;
rState_x4_ThermalDelta := rProcessTempOutlet_DegC - rProcessTempInlet_DegC;

(* 1-Step Receding Horizon State Projections *)
rPredDiffPress_bar := (rA11 * rState_x1_DiffPressErr) + (rA12 * rState_x2_GvfDeviation) + 
                      (rA13 * rState_x3_SpeedError)   + (rA14 * rState_x4_ThermalDelta) +
                      (rE11 * rInletPressRate_bars)   + (rE12 * rGvfRate_Pcts);

rPredGvf_Pct := (rA21 * rState_x1_DiffPressErr) + (rA22 * rState_x2_GvfDeviation) + 
                (rE21 * rInletPressRate_bars)   + (rE22 * rGvfRate_Pcts);

rPredThermalDelta_DegC := (rA41 * rState_x1_DiffPressErr) + (rA42 * rState_x2_GvfDeviation) + 
                          (rA44 * rState_x4_ThermalDelta) + (rE42 * rGvfRate_Pcts);

(* ---------------------------------------------------------------------------------------------------------------------
   LAYER 5: FINITE STATE MACHINE (ISA-88 MODULAR SUBSEA SEQUENCING)
   --------------------------------------------------------------------------------------------------------------------- *)
CASE iState OF

    0: (* STATE_SUBSEA_COLD_INIT: Pre-start integrity, barrier fluid and valve stroking verification *)
        bSystemReady            := FALSE;
        bDegradedModeActive     := FALSE;
        rRecirculationValve_Pct := 100.0; (* Pre-position ARV to 100% full open for soft unloaded start *)
        rVsdSpeedSetpoint_rpm   := 0.0;
        wSystemStatusWord       := 16#0001;

        tonStartupPermissive(
            IN := bMasterEnable AND (rBarrierFluidDiffPress_bar >= 22.0) AND (iHealthySensorCount >= 2),
            PT := T#10S
        );

        IF tonStartupPermissive.Q THEN
            tonStartupPermissive(IN := FALSE);
            iPreviousState        := 0;
            udiStateRunTimeCycles := 0;
            iState                := 10; (* Transition to Pressurized Standby / Minimum Idle *)
        END_IF;

    10: (* STATE_STANDBY_PRESSURIZED_IDLE: Minimum speed circulation & thermal stabilization *)
        bSystemReady            := TRUE;
        bDegradedModeActive     := FALSE;
        rRecirculationValve_Pct := 100.0; (* 100% Recirculation to establish fluid film on mechanical seals *)
        rVsdSpeedSetpoint_rpm   := rMinSpeed_rpm; (* Spin to 1800 rpm idle *)
        wSystemStatusWord       := 16#0010;

        rCumulativeRecircTime_Hours := rCumulativeRecircTime_Hours + (0.5 / 3600.0);

        IF bMasterEnable AND bAutoModeSelect AND (rPumpSpeedFeedback_rpm >= (rMinSpeed_rpm - 50.0)) THEN
            iPreviousState        := 10;
            udiStateRunTimeCycles := 0;
            iState                := 20; (* Engage Closed-Loop Boosting *)
        ELSIF NOT bMasterEnable THEN
            iState := 0;
        END_IF;

    20: (* STATE_NORMAL_MPC_BOOSTING: Optimal Multiphase Boosting & Continuous ARV Modulation *)
        bSystemReady        := TRUE;
        bDegradedModeActive := (iHealthySensorCount < 3);
        wSystemStatusWord   := 16#0020;

        (* Sub-Loop A: Anti-Recirculation Valve (ARV) Position Synthesis via MPC *)
        (* Target surge margin: 18.0%. If surge margin drops below 18%, modulate ARV open *)
        IF rSurgeMargin_Pct < 18.0 THEN
            rRecirculationValve_Pct := (18.0 - rSurgeMargin_Pct) * 4.50 + 8.0;
        ELSE
            (* Closed-loop leakage trim: Keep valve slightly cracked (2.0%) to prevent hydrate freeze-in *)
            rRecirculationValve_Pct := 2.0;
        END_IF;

        (* High GVF anticipation bias: If predicted GVF > 85%, ramp ARV open to prevent gas lock *)
        IF (rGvf_Filt_Pct > 85.0) OR (rPredGvf_Pct > 15.0) THEN
            rRecirculationValve_Pct := rRecirculationValve_Pct + ((rGvf_Filt_Pct - 85.0) * 3.2);
        END_IF;

        (* Dynamic Saturation Limits on ARV Command *)
        IF rRecirculationValve_Pct > 100.0 THEN
            rRecirculationValve_Pct := 100.0;
        ELSIF rRecirculationValve_Pct < 2.0 THEN
            rRecirculationValve_Pct := 2.0;
        END_IF;

        (* Sub-Loop B: VSD Compressor Shaft Speed Modulation via MPC Boost Tracking *)
        (* Error between target differential pressure and predicted boost *)
        IF rDifferentialPress_bar < rTargetDiffPress_bar THEN
            rVsdSpeedSetpoint_rpm := rVsdSpeedSetpoint_rpm + 
                                     ((rTargetDiffPress_bar - rDifferentialPress_bar) * 12.0) - 
                                     (rPredDiffPress_bar * 4.0);
        ELSIF rDifferentialPress_bar > (rTargetDiffPress_bar + 2.0) THEN
            rVsdSpeedSetpoint_rpm := rVsdSpeedSetpoint_rpm - 
                                     ((rDifferentialPress_bar - rTargetDiffPress_bar) * 15.0);
        END_IF;

        (* Mechanical & Thermal Speed Constraints *)
        IF rVsdSpeedSetpoint_rpm > rRatedSpeed_rpm THEN
            rVsdSpeedSetpoint_rpm := rRatedSpeed_rpm;
        ELSIF rVsdSpeedSetpoint_rpm < rMinSpeed_rpm THEN
            rVsdSpeedSetpoint_rpm := rMinSpeed_rpm;
        END_IF;

        (* Motor Overload Protective Speed Trimming *)
        IF (rMotorShaftTorque_kNm > (rMaxMotorTorque_kNm * 0.92)) OR (rMotorCurrent_A > (rMaxMotorCurrent_A * 0.90)) THEN
            rVsdSpeedSetpoint_rpm := rVsdSpeedSetpoint_rpm - 35.0;
        END_IF;

        (* Dynamic Transitions to Dedicated Abatement States *)
        IF (rGvf_Filt_Pct >= 92.0) OR (rGvfRate_Pcts > 8.0) THEN
            iPreviousState        := 20;
            udiStateRunTimeCycles := 0;
            iState                := 30; (* Enter High GVF / Gas Lock Mitigation State *)
        ELSIF (rMotorShaftTorque_kNm > rMaxMotorTorque_kNm) OR (rMotorCurrent_A > rMaxMotorCurrent_A) THEN
            iPreviousState        := 20;
            udiStateRunTimeCycles := 0;
            iState                := 40; (* Enter Heavy Liquid Slug Torque Overload State *)
        ELSIF (iHealthySensorCount <= 1) THEN
            iPreviousState        := 20;
            udiStateRunTimeCycles := 0;
            iState                := 50; (* Degraded Sensor Fallback State *)
        END_IF;

    30: (* STATE_HIGH_GVF_GAS_LOCK_PREVENTION: Rapid Anti-Surge Bypass & Gas Pocket Attenuation *)
        bSystemReady            := TRUE;
        bDegradedModeActive     := TRUE;
        wSystemStatusWord       := 16#0030;
        wAlarmWord.4            := TRUE; (* High GVF Gas Lock Warning Active *)
        udiGasSlugEventCounter  := udiGasSlugEventCounter + 1;

        (* Force Fast ARV Opening: Re-inject stored liquid inventory from discharge scrubbers *)
        rRecirculationValve_Pct := 65.0 + ((rGvf_Filt_Pct - 90.0) * 3.5);
        IF rRecirculationValve_Pct > 100.0 THEN
            rRecirculationValve_Pct := 100.0;
        END_IF;

        (* Trim pump speed down toward 3200 rpm to prevent rotor overheating in dry gas *)
        IF rVsdSpeedSetpoint_rpm > 3200.0 THEN
            rVsdSpeedSetpoint_rpm := rVsdSpeedSetpoint_rpm - 40.0;
        ELSIF rVsdSpeedSetpoint_rpm < rMinSpeed_rpm THEN
            rVsdSpeedSetpoint_rpm := rMinSpeed_rpm;
        END_IF;

        rCumulativeRecircTime_Hours := rCumulativeRecircTime_Hours + (0.5 / 3600.0);

        (* Recovery Condition: GVF stabilized below 82% and surge margin safely restored *)
        IF (rGvf_Filt_Pct < 82.0) AND (rSurgeMargin_Pct >= 20.0) THEN
            wAlarmWord.4          := FALSE;
            iPreviousState        := 30;
            udiStateRunTimeCycles := 0;
            iState                := 20; (* Return to Normal Closed Loop *)
        ELSIF (rProcessTempOutlet_DegC > 125.0) THEN
            (* Thermal limit exceeded due to dry gas friction: Emergency fallback *)
            iState := 50;
        END_IF;

    40: (* STATE_LIQUID_SLUG_TORQUE_LIMITING: Pure Liquid Slug Impact Absorption *)
        bSystemReady               := TRUE;
        bDegradedModeActive        := TRUE;
        wSystemStatusWord          := 16#0040;
        wAlarmWord.6               := TRUE; (* Liquid Slug Torque Overload Alarm *)
        udiLiquidSlugEventCounter  := udiLiquidSlugEventCounter + 1;

        (* Modulate ARV to 35% to bypass liquid slug portion and unload stage differential *)
        rRecirculationValve_Pct := 35.0;

        (* Aggressive Speed Rollback to shed electromagnetic torque on subsea motor *)
        IF rVsdSpeedSetpoint_rpm > (rMinSpeed_rpm + 200.0) THEN
            rVsdSpeedSetpoint_rpm := rVsdSpeedSetpoint_rpm - 85.0;
        END_IF;

        (* Recovery Condition: Motor current and torque normalized below 82% rated *)
        IF (rMotorShaftTorque_kNm < (rMaxMotorTorque_kNm * 0.82)) AND 
           (rMotorCurrent_A < (rMaxMotorCurrent_A * 0.82)) AND 
           (rGvf_Filt_Pct > 25.0) THEN
            wAlarmWord.6          := FALSE;
            iPreviousState        := 40;
            udiStateRunTimeCycles := 0;
            iState                := 20; (* Return to Normal Boosting *)
        END_IF;

    50: (* STATE_DEGRADED_SENSOR_FALLBACK: Conservative Open-Loop Envelope Tracking *)
        bSystemReady        := FALSE;
        bDegradedModeActive := TRUE;
        wSystemStatusWord   := 16#0050;
        wAlarmWord.10       := TRUE; (* Degraded Operation Status Active *)

        (* Safe open-loop ARV scheduling based on gross flow and nominal speed *)
        rRecirculationValve_Pct := 45.0;
        rVsdSpeedSetpoint_rpm   := 2800.0; (* Lock to conservative intermediate speed *)

        rCumulativeRecircTime_Hours := rCumulativeRecircTime_Hours + (0.5 / 3600.0);

        (* Return to normal if sensor consensus is re-established *)
        IF (iHealthySensorCount >= 2) AND bAutoModeSelect THEN
            wAlarmWord.10         := FALSE;
            iPreviousState        := 50;
            udiStateRunTimeCycles := 0;
            iState                := 20;
        END_IF;

    99: (* STATE_EMERGENCY_SHUTDOWN_TRIP: Tripped / Post-ESD Hydrate Mitigation Sequence *)
        bSystemReady            := FALSE;
        bDegradedModeActive     := FALSE;
        rVsdSpeedSetpoint_rpm   := 0.0;
        rRecirculationValve_Pct := 100.0; (* Full open bypass to equalize suction and discharge *)
        wSystemStatusWord       := 16#9999;

        IF bSubseaSafetyEStopOk AND (rBarrierFluidDiffPress_bar >= 20.0) AND (rDischargePressure_bar < 250.0) THEN
            iPreviousState        := 99;
            udiStateRunTimeCycles := 0;
            iState                := 0; (* Reset to Cold Init *)
        END_IF;

END_CASE;

(* ---------------------------------------------------------------------------------------------------------------------
   LAYER 6: COMPREHENSIVE ISA-18.2 ALARM & DIAGNOSTIC WORD ENCODING
